// Which senders we handle. Add a vendor here and give it an amount pattern
// in ParseEmail; nothing else in the workflow needs to change.
const VENDOR_MATCHERS = [
  { key: "contabo", pattern: /contabo/i },
  { key: "godaddy", pattern: /godaddy/i },
];

const item = $input.item.json;
const text = item.textPlain || "";

const hit = VENDOR_MATCHERS.find((v) => v.pattern.test(text));

item.vendorKey = hit ? hit.key : null;
item.shouldProcess = !!hit;

return item;

const item = $input.item.json;
const text = $input.item.json.textPlain;

// How to find the charged total for each vendor. First pattern that matches
// wins, so order matters: put the most specific anchor first and looser
// phrasing after it as a fallback.
//
// Each pattern must capture: 1 = currency symbol, 2 = amount.
const AMOUNT_PATTERNS = {
  contabo: [
    // "...charged $10.94 to your credit card..."
    /charged\s+([€$])\s*([0-9][0-9,]*(?:\.[0-9]{2})?)/i,
  ],
  godaddy: [
    // "Total: $19.99" on its own line. Anchored to line start on purpose:
    // an unanchored /Total:/ also matches the "Subtotal:" line directly
    // above it, which would post the pre-tax amount.
    /^Total:\s*([€$])\s*([0-9][0-9,]*(?:\.[0-9]{2})?)/im,
    // "We have billed your Visa card ... for the amount of $19.99."
    /amount of\s+([€$])\s*([0-9][0-9,]*(?:\.[0-9]{2})?)/i,
  ],
};

function toYmd(d) {
  const dt = new Date(d);
  if (!Number.isFinite(dt.getTime())) return null;
  return dt.toISOString().slice(0, 10);
}

const MONTHS = {
  jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6,
  jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12,
};

const pad = (n) => String(n).padStart(2, "0");

// The date the vendor issued the receipt, read from the forwarded "Date:"
// header in the body -- NOT item.date, which is when *we* forwarded it and
// can land in the wrong month.
//
// Deliberately does not use new Date(): Gmail writes "Fri, Jul 31, 2026 at
// 11:47 PM" with a narrow no-break space (U+202F) before AM/PM, which
// new Date() rejects outright as Invalid Date. Building the string from
// captured parts also sidesteps any timezone shifting of the calendar day.
function receiptDateFrom(body) {
  const line = body.match(/^\s*Date:\s*(.+)$/m);
  if (!line) return null;
  const raw = line[1].trim();

  // Gmail forward style: "Fri, Jul 31, 2026 at 11:47 PM"
  let m = raw.match(/([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),\s*(\d{4})/);
  if (m) {
    const mo = MONTHS[m[1].toLowerCase()];
    if (mo) return `${m[3]}-${pad(mo)}-${pad(m[2])}`;
  }

  // RFC 2822 style: "Tue, 23 Jun 2026 09:17:00 -0700"
  m = raw.match(/(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})/);
  if (m) {
    const mo = MONTHS[m[2].toLowerCase()];
    if (mo) return `${m[3]}-${pad(mo)}-${pad(m[1])}`;
  }

  // ISO style: "2026-06-23"
  m = raw.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;

  return null;
}

// Fall back to the forward date only if the body has no usable header.
let expenseDate = receiptDateFrom(text) || (item.date ? toYmd(item.date) : null);

const mFrom = text.match(/^From:\s*([^<\r\n]+)\s*<([^>\r\n]+)>/m);
const vendor = mFrom ? mFrom[1].trim() : "Unknown";
const vendorEmail = mFrom ? mFrom[2].trim() : null;

// vendorKey is set by ShouldProcess; fall back to contabo's pattern so an
// item that somehow arrives without one behaves as it did before.
const patterns = AMOUNT_PATTERNS[item.vendorKey] || AMOUNT_PATTERNS.contabo;

let mAmt = null;
for (const re of patterns) {
  mAmt = text.match(re);
  if (mAmt) break;
}

const symbol = mAmt ? mAmt[1] : null;
// strip thousands separators before Number(): "1,234.56" -> 1234.56
const amount = mAmt ? Number(mAmt[2].replace(/,/g, "")) : null;
const currency = symbol === "$" ? "USD" : symbol === "€" ? "EUR" : null;

const mSubject = text.match(/^Subject:\s*(.+)$/m);
const subject = mSubject ? mSubject[1].trim() : item.subject || null;

return {
  json: {
    ...item,
    vendor,
    vendorEmail,
    expenseDate,
    amount,
    currency,
    subject,
  },
};

// After Merge node.
//
// The merge hands us two different items: the Invoice Ninja vendors response
// (has .data) and the parsed email (has .vendor). Pick each out by shape
// rather than by position -- reading the vendor name off $json silently gave
// "" here, and the .includes("") fallback below then matched *every* vendor,
// so the first one in the list won regardless of who actually billed us.
const items = $input.all().map((i) => i.json);

const vendorsItem = items.find((i) => Array.isArray(i.data)) || {};
const email = items.find((i) => i.vendor !== undefined) || items[items.length - 1] || {};

const vendors = (vendorsItem.data || []).map((v) => ({
  id: v.id,
  name: v.name || "",
  nameLc: (v.name || "").toLowerCase(),
}));

const vendorName = (email.vendor || "").trim().toLowerCase();

// Only attempt a match when we actually have a name. Every substring test
// below is true for "", so an empty name must never reach them.
let match = null;
if (vendorName) {
  match =
    vendors.find((v) => v.nameLc === vendorName) ||
    vendors.find((v) => v.nameLc && v.nameLc.includes(vendorName)) ||
    vendors.find((v) => v.nameLc && vendorName.includes(v.nameLc)) ||
    null;
}

function toLocalYmd(val) {
  const d = new Date(val);
  if (!Number.isFinite(d.getTime())) return null;
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

return {
  json: {
    // expenseDate is the vendor's own receipt date, parsed in ParseEmail.
    // toLocalYmd(email.date) is the date we forwarded it, kept only as a
    // fallback for bodies with no parseable Date: header.
    date: email.expenseDate || toLocalYmd(email.date),
    amount: email.amount,
    from: email.from,
    subject: email.subject,
    vendorId: match ? match.id : null,
    vendorMatchedName: match ? match.name : null,
    vendorFound: !!match,
    vendorCandidates: vendors.slice(0, 10).map((v) => ({ id: v.id, name: v.name })),
  },
};
